/**
 * @name Path traversal in file operations
 * @description User-controlled file paths without proper validation can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/click-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters to functions that accept file paths
    exists(DataFlow::ParameterNode param |
      source = param and
      (
        param.getParameter().getName() in ["filename", "path", "file", "filepath", "name", "fn"]
      )
    )
    or
    // Return values from path-related functions
    exists(DataFlow::CallCfgNode call |
      source = call and
      (
        call = API::moduleImport("os").getMember("path").getMember(["join", "abspath", "normpath"]).getACall() or
        call = API::moduleImport("pathlib").getMember("Path").getACall()
      )
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File system access operations
    sink = any(FileSystemAccess fsa).getAPathArgument()
    or
    // Direct file operations
    exists(DataFlow::CallCfgNode call |
      sink = call.getArg(_) and
      (
        call = API::builtin("open").getACall() or
        call = API::moduleImport("os").getMember(["remove", "unlink", "rmdir", "mkdir", "makedirs"]).getACall() or
        call = API::moduleImport("shutil").getMember(["rmtree", "copy", "copy2", "copytree", "move"]).getACall()
      )
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled path"
